     "$ref": "#/definitions/aspect"
    },
    "design_knowledge_reflection": {
     "$ref": "#/definitions/aspect"
    },
    "doc_freshness": {
     "$ref": "#/definitions/aspect"
    },
    "prompt_quality": {
     "$ref": "#/definitions/aspect"
    }
   }
  },
  "audit_delegations": {
   "type": "array",
   "description": "独立 context (Task fork) で起動した監査 sub-agent の receipt 一覧。auditor が C05 自身でない観点 (primary) と、宣言された sub-input 監査 (matrix_coverage の C06) に 1 件ずつ必須。PostToolUse hook が書く fork 台帳の session・tool・response digest・verdict と突合され、裏取りできない帰属または判定は fail-closed で violation になる。",
