    "$ref": "#/definitions/gate_result"
   }
  },
  "findings": {
   "type": "array",
   "minItems": 1,
   "items": {
    "$ref": "#/definitions/finding"
   }
  },
  "gaps": {
   "type": "array",
   "items": {
    "type": "string",
    "minLength": 1
   },
   "description": "不足事項一覧。verdict=FAIL のとき非空 (elicit/doc-fetch/compile への差し戻し材料)。"
  }
 },
