  "required": [
   "aspect",
   "role",
   "auditor",
   "component",
   "dispatch",
   "verdict",
   "evidence"
  ],
  "properties": {
   "aspect": {
    "type": "string",
    "enum": [
     "foundation_trace",
     "decision_guidance",
     "matrix_coverage",
     "design_knowledge_reflection",
     "doc_freshness",
     "prompt_quality"
    ]
   },
   "role": {
    "type": "string",
    "enum": [
     "primary",
     "sub_input"
    ],
    "description": "primary=当該観点の一次根拠 / sub_input=補助根拠 (独立観点へ昇格させない)"
   },
   "auditor": {
    "type": "string",
    "minLength": 1,
    "description": "plugin 同梱の agent 定義 (agents/<auditor>.md) に実在する名前"
   },
   "component": {
    "type": "string",
    "minLength": 1
   },
   "dispatch": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "tool",
     "subagent_type",
     "session_id",
     "response_sha256"
    ],
    "properties": {
     "tool": {
      "enum": [
       "Task",
       "Agent"
      ],
      "description": "subagent 起動ツール名の観測値 (旧ハーネス/Codex 系='Task', 現行 Claude Code='Agent')。aggregate-completeness.py の LEDGER_TOOL_NAMES と整合"
     },
     "subagent_type": {
      "type": "string",
      "minLength": 1,
      "description": "auditor と一致すること。fork 台帳の subagent_type と突合される"
     },
     "session_id": {
      "type": "string",
      "minLength": 1,
      "description": "fork を起動した評価 session の id。宣言単独では自己申告のため、fork 台帳 (hook が harness 観測値を記録) に同一 (session_id, subagent_type) の行が実在するときだけ裏取り成立 (issue: HarnessHub-x4o)。必須 receipt 全件で同一 session を名指しすること (単一 run 収束)"
     },
     "response_sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$",
      "description": "PostToolUse hook が観測した監査 response の canonical sha256。台帳に同一 session・subagent・tool・digest の行があり、そこに記録された audit_verdict が receipt.verdict と一致するときだけ帰属と判定の裏取りが成立する"
     }
    }
   },
   "verdict": {
    "type": "string",
    "enum": [
     "PASS",
     "FAIL",
     "INDETERMINATE"
    ],
    "description": "role=primary のとき aspects[aspect].verdict と一致必須 (監査判定の忠実転記)"
   },
   "evidence": {
    "type": "array",
    "minItems": 1,
    "items": {
     "type": "string",
     "minLength": 1
    }
   }
  }
 },
 "gate_result": {
  "type": "object",
  "additionalProperties": false,
  "required": [
   "id",
   "name",
   "exit_code"
  ],
  "properties": {
   "id": {
    "type": "string",
    "minLength": 1
   },
   "name": {
    "type": "string",
    "minLength": 1
   },
