    "type": "array",
    "items": {
     "type": "string"
    }
   },
   "command": {
    "type": "array",
    "items": {
     "type": "string"
    }
   },
   "exit_code": {
    "type": "integer"
   },
   "stdout": {
    "type": "string"
   },
   "stderr": {
    "type": "string"
   }
  }
 },
 "finding": {
  "type": "object",
  "additionalProperties": false,
  "required": [
   "severity",
   "bucket",
   "observation"
  ],
  "properties": {
   "severity": {
    "type": "string",
    "enum": [
     "high",
     "medium",
     "low",
     "info"
    ]
   },
   "bucket": {
    "type": "string",
    "minLength": 1
   },
   "observation": {
    "type": "string",
    "minLength": 1
   },
   "suggested_fix": {
    "type": "string"
   },
   "evidence": {
    "type": "array",
    "items": {
     "type": "string"
    }
   }
  }
 }
}

